def annotate(xs: List<&2,U32>, +sum: U32) -> List<&2,U32>:
  match xs:
    case Nil{}: Nil{}
    case h <> t:
      U32.add(h,sum) <> annotate(t,sum)

def annotate(xs: List<&2,U32>, +whole: List<&2,U32>) -> List<&2,U32>:
  match xs:
    case Nil{}: Nil{}
    case h <> t:
      U32.add(h,total(whole)) <> annotate(t,whole)

def walk(xs: List<&2,U32>, +i: U32) -> List<&2,U32>:
  match xs:
    case Nil{}: Nil{}
    case h <> t:
      U32.mul(h,i) <> walk(t,U32.add(i,1))

def walk(+xs: List<&2,U32>, n: Nat, +i: Nat) -> List<&2,U32>:
  match n:
    case 0n: Nil{}
    case 1n+p:
      U32.mul(value(List.get(&2,U32,xs,i)),U32.from_nat(1n+i)) <> walk(xs,p,1n+i)

def solve(xs: List<&2,U32>) -> List<&2,U32>:
  match xs:
    case Nil{}: Nil{}
    case h <> t: U32.add(U32.mul(h,3),1) <> solve(t)
